actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput

String activeUserId = ec.user.getUserId() ?: "system_ide_user"
String activeSessionId = context.sessionId ?: ec.context.sessionId

// 🎯 A. RESOLVE TARGET URI
String targetUri = ""
if (targetNodeId && targetNodeId.contains("#") && targetNodeId.startsWith("component://")) {
    targetUri = targetNodeId.split("#")[0]
}
if (!targetUri || targetUri.trim() == "") {
    String rawUri = context.activeArtifactLocation ?: ec.context.activeArtifactLocation ?: context.focusCoordinate ?: ""
    targetUri = rawUri.contains("#") ? rawUri.split("#")[0] : rawUri
}
if (!targetUri || targetUri.trim() == "") {
    targetUri = (ec.context.get("activeArtifactLocation") ?: "").toString()
}

// 🎯 B. HYDRATE BUFFER (ADK Session State -> DB Fallback)
String currentMetaJsonStr = context.activeLayoutBuffer
String bufferId = context.activeLayoutBufferId

if (activeSessionId) {
    def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
    def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()
    if (sessionOpt && sessionOpt.isPresent()) {
        String stateBuffer = sessionOpt.get().state().get("activeLayoutBuffer")
        if (stateBuffer && stateBuffer.startsWith("{")) {
            currentMetaJsonStr = stateBuffer
        }
    }
}

if (!currentMetaJsonStr || !currentMetaJsonStr.trim().startsWith("{")) {
    if (targetUri && targetUri.trim() != "") {
        // 🎯 Fetch list ordered by latest timestamp to guarantee reading newest history entry
        def bufferList = ec.entity.find("org.moqui.ai.WorkspaceBuffer")
            .condition("artifactUri", targetUri)
            .condition("userId", activeUserId)
            .orderBy("-lastUpdatedStamp")
            .useCache(false)
            .list()

        def bufferRow = bufferList ? bufferList[0] : null
        if (bufferRow?.metaJsonBuffer) {
            currentMetaJsonStr = bufferRow.metaJsonBuffer
            bufferId = bufferRow.workspaceBufferId
        }
    }
}

// 🎯 C. PARSE BUFFER OR INITIALIZE FROM PHYSICAL XML ON DISK
Map layoutTree = [:]
boolean parseFailed = false

if (currentMetaJsonStr && currentMetaJsonStr.trim().startsWith("{") && !currentMetaJsonStr.contains("[...]")) {
    try {
        layoutTree = new JsonSlurper().parseText(currentMetaJsonStr) as Map
    } catch (Exception parseEx) {
        ec.logger.warn("⚠️ [manage#WorkspaceBuffer] Invalid JSON buffer in DB/State (${parseEx.message}). Reading XML from disk...")
        parseFailed = true
    }
} else {
    parseFailed = true
}

// 🎯 RECOVERY: Read directly from physical XML file on disk if DB buffer is missing!
if (parseFailed || layoutTree.isEmpty()) {
    if (targetUri && targetUri.trim() != "") {
        try {
            ec.logger.info("📄 [manage#WorkspaceBuffer] No DB buffer found. Parsing physical XML file from disk: '${targetUri}'")
            Map parseResult = ec.service.sync().name("org.moqui.ai.AgiWorkspaceServices.parse#XmlToTree")
                .parameter("artifactUri", targetUri)
                .call()
            if (parseResult?.layoutTree) {
                layoutTree = parseResult.layoutTree as Map
            }
        } catch (Exception xmlEx) {
            ec.logger.error("❌ Failed to parse physical XML file [${targetUri}]: ${xmlEx.message}")
        }
    }

    // Absolute last-resort fallback if file does not exist on disk
    if (layoutTree.isEmpty()) {
        String screenName = targetUri ? targetUri.split("/")[-1].replace(".xml", "") : "ActiveScreen"
        ec.logger.info("🛠️ [manage#WorkspaceBuffer] Initializing default root tree for URI: '${targetUri}'")
        layoutTree = [
            screen: screenName,
            location: targetUri ?: "",
            mariaId: screenName + "#root",
            widgets: [
                [
                    type: "form-single",
                    id: "patient_intake",
                    mariaId: (targetUri ?: "") + "#patient_intake",
                    children: []
                ]
            ]
        ]
    }
}

// 🎯 D. EXECUTE TREE MUTATION
Map mutationResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.mutate#JsonTree")
    .parameters([layoutTree: layoutTree, targetNodeId: targetNodeId, action: action, payloadNode: payloadNode])
    .call()

boolean isMutated = Boolean.TRUE.equals(mutationResult.mutated)
context.mutated = isMutated

if (isMutated) {
    String updatedMetaJson = JsonOutput.toJson(layoutTree)

    // Persist newly populated tree directly to WorkspaceBuffer using service call
    ec.service.sync().name("org.moqui.ai.AgiWorkspaceServices.store#WorkspaceBuffer")
        .parameters([
            workspaceBufferId: bufferId,
            artifactUri: targetUri,
            userId: activeUserId,
            metaJsonBuffer: updatedMetaJson
        ])
        .call()

    // ADK Session Memory Sync
    if (activeSessionId) {
        def runner = org.moqui.adk.AdkManager.runnerForSession(activeSessionId)
        def sessionOpt = runner.sessionService().getSession("moqui-adk", activeUserId, activeSessionId, java.util.Optional.empty()).blockingGet()
        if (sessionOpt && sessionOpt.isPresent()) {
            sessionOpt.get().state().put("activeLayoutBuffer", updatedMetaJson)
        }
    }

    context.updatedMetaJson = updatedMetaJson
    context.targetUri = targetUri
    context.status = "SUCCESS"
} else {
    ec.logger.warn("❌ [manage#WorkspaceBuffer] Target container [${targetNodeId}] not found in tree.")
    context.status = "NODE_NOT_FOUND"
}

ec.logger.info("🚀 [TOOL EXECUTION] add#FormField -> targetNodeId=${targetNodeId}, label=${label}")
String rawName = context.name ?: "" String cleanName = (rawName.trim() != "") ? rawName.trim() : label.replaceAll("[^a-zA-Z0-9_]", "")
String resolvedUri = targetNodeId.contains("#") ? targetNodeId.split("#")[0] : (context.activeArtifactLocation ?: "")
// 🎯 1. HIPAA PHI / Medical Field Auto-Detection Set<String> sensitivePhiFields = [ "ssn", "socialsecurity", "dob", "birthdate", "medicalhistory", "diagnosis", "diagnosiscode", "prescription", "patientname", "medication", "treatmentplan", "insuranceid", "vital" ] as Set
String normalizedCheck = (cleanName + label).toLowerCase().replaceAll("[^a-z0-9]", "") boolean autoPhiEncrypt = "true".equalsIgnoreCase(context.encrypt) || sensitivePhiFields.any { normalizedCheck.contains(it) }
// 🎯 2. Populate children with an m-text-line input node so QMETA AST renders on the canvas Map dynamicFieldNode = [ id: java.util.UUID.randomUUID().toString(), "@type": "FormField", name: cleanName, title: label, mariaId: resolvedUri + "#" + cleanName, children: [ [ "@type": "m-text-line", attributes: [ placeholder: "", disabled: "false" ], children: [] ] ] ]
// Enforce HIPAA Encryption if PHI data detected if (autoPhiEncrypt) { dynamicFieldNode["encrypt"] = "true" ec.logger.info("🔒 [HIPAA Enforcement] Applied encrypt='true' on field: ${cleanName}") }
// Stamp AI Intent if provided or default command dynamicFieldNode["ai-intent"] = context.aiIntent ?: "/add-field ${cleanName}"
// Delegate hydration, mutation, and persistence entirely to manage#WorkspaceBuffer Map bufferResult = ec.service.sync().name("org.moqui.ai.mcp.LayoutServices.manage#WorkspaceBuffer") .parameters([ targetNodeId: targetNodeId, action: "APPEND", payloadNode: dynamicFieldNode, activeLayoutBuffer: context.activeLayoutBuffer, activeLayoutBufferId: context.activeLayoutBufferId, activeArtifactLocation: context.activeArtifactLocation ]) .call()
context.status = bufferResult.status context.updatedMetaJson = bufferResult.updatedMetaJson

def processNode
processNode = { Map node ->
    String cleanTargetId = targetNodeId.contains("#") ? targetNodeId.split("#")[1] : targetNodeId

    boolean isTarget = (node.id == targetNodeId) || 
        (node.mariaId == targetNodeId) || 
        (node.id == cleanTargetId) ||
        (node.name == cleanTargetId) ||
        (node.mariaId?.toString()?.endsWith("#" + cleanTargetId))

    if (isTarget) {
        if ("APPEND".equalsIgnoreCase(action)) {
            // 🎯 Normalize list key: Ensure we append to whichever array already holds existing fields
            if (node.children == null && node.widgets != null) {
                node.children = node.widgets
            }
            if (node.children == null) {
                node.children = []
            }

            // Append without clearing existing fields
            node.children.add(payloadNode)
            return true
        } else if ("REPLACE".equalsIgnoreCase(action)) {
            node.clear()
            node.putAll(payloadNode)
            return true
        }
    }

    def childList = node.children ?: node.widgets
    if (childList && childList instanceof List) {
        if ("DELETE".equalsIgnoreCase(action)) {
            boolean removed = childList.removeIf { 
                it.id == targetNodeId || it.mariaId == targetNodeId || it.mariaId?.toString()?.endsWith("#" + targetNodeId)
            }
            if (removed) return true
        }
        for (child in childList) {
            if (child instanceof Map && processNode(child as Map)) return true
        }
    }
    return false
}
context.mutated = processNode(layoutTree)
